import React, { useEffect, useState, useRef } from "react";
import { Link } from "react-router-dom";
import DataTable from "react-data-table-component";
import { makeApiRequest } from "../../axiosService/ApiCall";
import { ToastContainer, toast } from "react-toastify";
import { Modal, Button } from "react-bootstrap";
import { MdLineWeight } from "react-icons/md";
import Select from "react-select";
import { MdRefresh } from "react-icons/md";
import { FaCalendarAlt, FaRegCopy } from "react-icons/fa";
import { DateRange } from "react-date-range";
import { enUS } from "date-fns/locale";
import "react-date-range/dist/styles.css";
import "react-date-range/dist/theme/default.css";

function AdminActivity() {
  const [limit, setLimit] = useState(10);
  const [page, setPage] = useState(1);
  const [data, setData] = useState([]);
  const [totalRows, setTotalRows] = useState(0);
  const [adminType, setAdminType] = useState("");

  // search/type/sort
  const [search, setSearch] = useState("");
  const [type, setType] = useState(null);

  // sortOrder as number (use consistent type)
  const [sortOrder, setSortOrder] = useState(-1);

  // date range state (keep nulls for display but provide valid fallback when rendering DateRange)
  const [range, setRange] = useState([
    {
      startDate: null,
      endDate: null,
      key: "selection",
    },
  ]);

  // formatted strings for UI display (en-CA => YYYY-MM-DD)
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");

  const [resetPaginationToggle, setResetPaginationToggle] = useState(false);

  // calendar popup
  const [showCalendar, setShowCalendar] = useState(false);
  const calendarRef = useRef(null);
  const dateButtonRef = useRef(null);

  // refresh animation flag (optional)
  const [isRefreshing, setIsRefreshing] = useState(false);

  // options
  const statusOptions = [
    { value: "Login", label: "Login" },
    { value: "withdrawRequest", label: "withdrawRequest" },
    { value: "SubAdmin Update", label: "SubAdmin Update" },
    { value: "SubAdmin Create", label: "SubAdmin Create" },
    { value: "AdminMove", label: "AdminMove" },
    { value: "Pair Updated", label: "Pair Updated" },
    { value: "userStatusUpdate", label: "userStatusUpdate" },
    { value: "Individual form Delete", label: "Individual form Delete" },
    { value: "Kyc form Delete", label: "Kyc form Delete" },
    { value: "Business form Delete", label: "Business form Delete" },
    { value: "siteSetting", label: "siteSetting" },
    { value: "Notification", label: "Notification" },
    { value: "CMS", label: "CMS" },
    { value: "TFA Disable", label: "TFA Disable" },
    { value: "Support Ticket", label: "Support Ticket" },
    { value: "SubAdmin Delete", label: "SubAdmin Delete" },
    { value: "Admin Address Update", label: "Admin Address Update" },
    { value: "Admin Address Create", label: "Admin Address Create" },
    //{value: "withdrawRequest", label: "withdrawRequest"}
  ];

  const sortOptions = [
    { value: 1, label: "Ascending" },
    { value: -1, label: "Descending" },
  ];

  const customStyles = {
    control: (base, state) => ({
      ...base,
      borderColor: state.isFocused ? "var(--color-1)" : "var(--color-1)",
      boxShadow: state.isFocused ? "0 0 0 1px var(--color-1)" : "none",
      borderRadius: "8px",
      fontSize: "13px",
      "&:hover": {
        borderColor: "var(--color-1)",
      },
      minWidth: "140px",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: "8px",
      marginTop: 4,
    }),
    singleValue: (base) => ({
      ...base,
      color: "#000",
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isSelected
        ? "var(--color-1)"
        : state.isFocused
          ? "#58f9b07c"
          : "white",
      color: state.isSelected ? "var(--theme-text-1)" : "black",
      ":active": {
        backgroundColor: "var(--color-1)",
      },
      cursor: "pointer",
      fontSize: "13px",
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 9999,
    }),
  };
  // -----------------------
  // close calendar when click outside
  // -----------------------
  useEffect(() => {
    const onDocClick = (e) => {
      if (
        showCalendar &&
        calendarRef.current &&
        !calendarRef.current.contains(e.target) &&
        dateButtonRef.current &&
        !dateButtonRef.current.contains(e.target)
      ) {
        setShowCalendar(false);
      }
    };
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [showCalendar]);

  // -----------------------
  // fetch data (include range in deps)
  // -----------------------
  useEffect(() => {
    AdminActivityres();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, limit, sortOrder, search, type, range]);
  // format date as YYYY-MM-DD in local timezone (no UTC shift)
  const formatDateLocal = (date) => {
    if (!date) return "";
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  };

  const AdminActivityres = async () => {
    try {
      let url = `admin-activity?page=${page}&limit=${limit}`;

      if (search) {
        url += `&search=${encodeURIComponent(search)}`;
      }
      if (type && type.value) {
        url += `&type=${encodeURIComponent(type.value)}`;
      }
      if (sortOrder !== undefined && sortOrder !== null) {
        url += `&sortOrder=${encodeURIComponent(sortOrder)}`;
      }

      // IMPORTANT: send date-only string (YYYY-MM-DD) to avoid timezone shifts
      // const startDateForUrl =
      //   range[0] && range[0].startDate
      //     ? range[0].startDate.toISOString().split("T")[0]
      //     : ""; 
      // console.log("startDateForUrl", startDateForUrl);  
      // const endDateForUrl =
      //   range[0] && range[0].endDate
      //     ? range[0].endDate.toISOString().split("T")[0]
      //     : ""; 
      // console.log("endDateForUrl", endDateForUrl);  

      const startDateForUrl = formatDateLocal(range[0]?.startDate);
      // console.log("startDateForUrl", startDateForUrl); 

      const endDateForUrl = formatDateLocal(range[0]?.endDate);
      // console.log("endDateForUrl", endDateForUrl); 


      if (startDateForUrl && endDateForUrl)
        url += `&startDate=${startDateForUrl}&endDate=${endDateForUrl}`;

      const params = {
        url,
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      // console.log("url",  url); 


      const AdminActivityData = await makeApiRequest(params);
      // console.log("AdminActivityData", AdminActivityData); 


      if (AdminActivityData?.status) {
        setData(AdminActivityData.data || []);
        setTotalRows(AdminActivityData.total || 0);
      } else {
        setData([]);
        setTotalRows(0);
      }
    } catch (err) {
      console.log("err", err);
      toast.error("Failed to fetch Admin Activity!");
    }
  };

  // admin_type get data
  useEffect(() => {
    adminTypeResData();
  }, []);

  const adminTypeResData = async () => {
    try {
      let params = {
        url: "view-edit-GetData",
        method: "GET",
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      };
      const adminTypeRes = await makeApiRequest(params);
      // console.log("adminTypeRes", adminTypeRes); 


      if (adminTypeRes.status) {
        setAdminType(adminTypeRes.data.admin_type);
      }
    } catch (error) {
      console.log("err", error);
    }
  };

  // -----------------------
  // handlers
  // -----------------------
  const handlePageChange = (newPage) => {
    setPage(newPage);
  };

  const handlePerRowsChange = (newLimit) => {
    setLimit(newLimit);
  };

  const handleDateChange = (item) => {

    // item.selection.startDate and endDate are Date objects
    setRange([item.selection]);

    const formatDate = (date) => {
      // en-CA gives YYYY-MM-DD
      return date ? date.toLocaleDateString("en-CA") : "";
    };

    setFromDate(formatDate(item.selection.startDate));
    setToDate(formatDate(item.selection.endDate));

    // reset pagination to first page when date filter changes
    setLimit(10);
    setPage(1);
  };

  const handleClearFilters = () => {
    setSearch("");
    setType(null);
    setSortOrder(-1);
    setRange([{ startDate: null, endDate: null, key: "selection" }]);
    setFromDate("");
    setToDate("");
    setPage(1);
    setResetPaginationToggle((p) => !p);
  };

  const handleToggleCalendar = () => {
    // only toggle visibility; don't call handleReset here (keeps UI same)
    setShowCalendar((s) => !s);
  };

  // -----------------------
  // columns (unchanged)
  // -----------------------
  const columns = [
    {
      name: "S.No",
      cell: (row, index) => (page - 1) * limit + (index + 1),
      width: "80px",
    },
    {
      name: "IP Address",
      selector: (row) => row.ip || "-",
      sortable: true,
      wrap: true,
    },
    {
      name: "Browser",
      selector: (row) => row.browser || "-",
      sortable: true,
      wrap: true,
    },
    {
      name: "Type",
      selector: (row) => row.type || "-",
      sortable: true,
      style: {
        whiteSpace: "normal",
        wordBreak: "break-word",
        lineHeight: "20px",
        padding: "6px 10px",
        minWidth: "180px",
        maxWidth: "350px",
      },
    },
    {
      name: "Admin Email",
      selector: (row) => row.AdminEmail || "-",
      sortable: true,
      wrap: true,
      style: {
        whiteSpace: "normal",
        wordBreak: "break-word",
        lineHeight: "20px",
        padding: "6px 10px",
        minWidth: "180px",
        maxWidth: "350px",
      },
    },
    {
      name: "Admin Name",
      selector: (row) => row.AdminName || "-",
      sortable: true,
      wrap: true,
    },
    {
      name: "Ref LastId",
      selector: (row) => row.lastId || "-",
      sortable: true,
      wrap: true,
      style: {
        whiteSpace: "normal",
        wordBreak: "break-word",
        lineHeight: "20px",
        padding: "6px 10px",
        minWidth: "180px",
        maxWidth: "350px",
      },
    },
    {
      name: "Comment",
      selector: (row) => row.comment || "-",
      sortable: true,
      wrap: true,
      style: {
        whiteSpace: "normal",
        wordBreak: "break-word",
        lineHeight: "20px",
        padding: "6px 10px",
        minWidth: "180px",
        maxWidth: "350px",
      },
    },
    {
      name: "Date Time",
      selector: (row) =>
        row.dateTime
          ? new Date(row.dateTime).toLocaleString("en-US", {
            year: "numeric",
            month: "short",
            day: "2-digit",
            hour: "2-digit",
            minute: "2-digit",
            second: "2-digit",
            hour12: true,
            timeZone: "UTC",
          })
          : "-",
      sortable: true,
      wrap: true,
    },
  ];

  // computedRanges for react-date-range (fallback to new Date() to avoid nulls)
  const computedRanges = [
    {
      startDate: range[0].startDate || new Date(),
      endDate: range[0].endDate || new Date(),
      key: "selection",
    },
  ];

  return (
    <div className="App">
      <div className="container-fluid">
        <div className="custom-saled-order">
          <div className="row">
            <div className="col-lg-12">
              <div className="py-3 d-flex justify-content-between">
                <h3 className="component-user text-center ms-lg-0">
                  Admin Activity Logs
                </h3>
              </div>

              <div className="row">
                <div className="col-lg-12">
                  <div className="d-flex calendor-form align-items-end gap-lg-4 flex-wrap mb-4">
                    <div>
                      <label htmlFor="email" className="form-label">
                        Name/Email
                      </label>
                      <input
                        id="email"
                        type="text"
                        placeholder="Search by Email or Name"
                        className="form search-bar form-control"
                        value={search}
                        onChange={(e) => {
                          setSearch(e.target.value);
                          setPage(1);
                        }}
                      />
                    </div>
                    <div>
                      <label className="form-label">Type</label>
                      <Select
                        options={statusOptions}
                        value={type}
                        onChange={(val) => {
                          setType(val);
                          setPage(1);
                        }}
                        id="border-css"
                        isClearable
                        styles={customStyles}
                        isSearchable={false}
                        components={{
                          IndicatorSeparator: () => null,
                        }}
                      />
                    </div>

                    <div className="filter-col">
                      <label className="form-label mb-1">Sort Order</label>
                      <Select
                        options={sortOptions}
                        value={
                          sortOptions.find((o) => o.value === sortOrder) || null
                        }
                        onChange={(opt) => {
                          setSortOrder(opt ? Number(opt.value) : -1);
                          setPage(1);
                        }}
                        styles={customStyles}
                        isSearchable={false}
                        components={{
                          IndicatorSeparator: () => null,
                        }}
                      />
                    </div>

                    <div>
                      <label className="form-label">Date</label>

                      <div
                        ref={calendarRef}
                        style={{ position: "relative", width: "250px" }}
                      >
                        <div
                          onClick={() => {
                            handleToggleCalendar();
                          }}
                          style={{
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "space-between",
                            padding: "6px",
                            border: "1px solid var(--color-1)",
                            borderRadius: "5px",
                            cursor: "pointer",
                            backgroundColor: "#fff",
                            fontSize: "14px",
                          }}
                          ref={dateButtonRef}
                        >
                          <span>
                            {fromDate && toDate
                              ? `${fromDate} - ${toDate}`
                              : "Select Date Range"}
                          </span>
                          <FaCalendarAlt style={{ color: "#555" }} />
                        </div>

                        {showCalendar && (
                          <div
                            style={{
                              position: "absolute",
                              top: "100%",
                              left: -80,
                              zIndex: 1000,
                              background: "#fff",
                              boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                              borderRadius: "5px",
                            }}
                          >
                            <DateRange
                              editableDateInputs={true}
                              onChange={handleDateChange}
                              moveRangeOnFirstSelection={false}
                              ranges={computedRanges}
                              locale={enUS}
                              rangeColors={["#58f9b0"]}
                            />
                          </div>
                        )}
                      </div>
                    </div>

                    <div>
                      <button
                        type="button"
                        className="form-label custom-nav-button-1 active cursor-pointer mb-0"
                        // onClick={() => {
                        //   // setIsRefreshing(true);
                        //   // setTimeout(() => setIsRefreshing(false), 700);
                        //   // // re-fetch with current filters
                        //   // AdminActivityres();
                        //   handleClearFilters
                        // }}
                        onClick={handleClearFilters}
                      >
                        <MdRefresh
                          style={{ fontSize: "24px" }}
                          className={isRefreshing ? "rotate-icon" : ""}
                        />
                      </button>
                    </div>
                  </div>

                  <div className="liquidity-table-1">
                    <DataTable
                      columns={columns}
                      data={data}
                      pagination
                      paginationServer
                      paginationTotalRows={totalRows}
                      onChangeRowsPerPage={(newPerPage) =>
                        handlePerRowsChange(newPerPage)
                      }
                      onChangePage={handlePageChange}
                      paginationPerPage={limit}
                      paginationRowsPerPageOptions={[5, 10, 15, 100, 500, 1000]}
                      paginationResetDefaultPage={resetPaginationToggle}
                      highlightOnHover
                      persistTableHead
                      noHeader={false}
                    />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <ToastContainer />
    </div>
  );
}

export default AdminActivity;
